## Step 5: Build a Search UI in Next.js


Here's a minimal server action + component pattern for a Next.js App Router project:


```text
// app/actions/search.ts
'use server'  ;


export     async     function     searchContent  (  query  :     string  )     {
if     (  !  query   ||   query  .  trim  (  )  .  length     <     2  )     return     [  ]  ;


const   res   =     await     fetch  (
{
method  :     'POST'  ,
headers  :     {
'Content-Type'  :     'application/json'  ,
}  ,
body  :     JSON  .  stringify  (  {
query  ,
limit  :     8  ,
status  :     'published'  ,
min_score  :     0.65  ,
}  )  ,
cache  :     'no-store'  ,
}
)  ;


if     (  !  res  .  ok  )     return     [  ]  ;
const     {   results   }     =     await   res  .  json  (  )  ;
return   results  ;
}
```


```text
// components/SearchBox.tsx
'use client'  ;


import     {   useState  ,   useTransition   }     from     'react'  ;
import     {   searchContent   }     from     '@/app/actions/search'  ;


export     function     SearchBox  (  )     {
const     [  query  ,   setQuery  ]     =     useState  (  ''  )  ;
const     [  results  ,   setResults  ]     =     useState  <  any  [  ]  >  (  [  ]  )  ;
const     [  isPending  ,   startTransition  ]     =     useTransition  (  )  ;


function     handleSearch  (  value  :     string  )     {
setQuery  (  value  )  ;
if     (  value  .  length     <     3  )     {
setResults  (  [  ]  )  ;
return  ;
}
startTransition  (  async     (  )     =>     {
const   hits   =     await     searchContent  (  value  )  ;
setResults  (  hits  )  ;
}  )  ;
}


return     (
<  div  >
<  input
type  =  "search"
value  =  {  query  }
onChange  =  {  (  e  )     =>     handleSearch  (  e  .  target  .  value  )  }
placeholder  =  "Search documentation..."
/  >
{  isPending   &&     <  p  >  Searching  ...  <  /  p  >  }
<  ul  >
{  results  .  map  (  (  r  )     =>     (
<  li key  =  {  r  .  object_id  }  >
<  a href  =  {  `  /blog/  ${  r  .  slug  }  `  }  >
{  r  .  snippet  }     <  span  >  (  {  Math  .  round  (  r  .  score     *     100  )  }  %   match  )  <  /  span  >
<  /  a  >
<  /  li  >
)  )  }
<  /  ul  >
<  /  div  >
)  ;
}
```


